from threetears.evals import Eval

from standings import Entry, table

def night_table(case):
    """Each team's place on the night's table."""
    return {"places": {place.team: place.place for place in table([Entry.from_row(e) for e in case["entries"]])}}


def every_team_placed(case, out):
    """Every team is in the place the quizmaster published."""
    return all(out["places"].get(p["team"]) == p["place"] for p in case["published"])

nights = Eval("data/nights.jsonl", runner=night_table, grader=[every_team_placed], k=1)
